-- Asset custody and governed internal communications.
alter table public.assets add column if not exists asset_tag text;
alter table public.assets add column if not exists condition text default 'GOOD' check(condition in ('NEW','GOOD','FAIR','DAMAGED','RETIRED'));
create unique index if not exists assets_tag_unique on public.assets(asset_tag) where deleted_at is null;
create table public.asset_custody_history(id bigint generated always as identity primary key,asset_id uuid not null references public.assets(id),employee_id uuid references public.employees(id),action text not null check(action in ('ASSIGNED','TRANSFERRED','RETURNED')),condition text,note text,recorded_by uuid not null references public.users(id),recorded_at timestamptz not null default now());
create table public.asset_maintenance(id uuid primary key default gen_random_uuid(),asset_id uuid not null references public.assets(id),description text not null,cost numeric(14,2) check(cost is null or cost>=0),started_at date not null,completed_at date,vendor text,created_by uuid not null references public.users(id),created_at timestamptz not null default now());
alter table public.asset_custody_history enable row level security;alter table public.asset_maintenance enable row level security;
drop policy if exists "visible assets" on public.assets;create policy "visible assets" on public.assets for select to authenticated using(deleted_at is null and (assigned_employee_id=public.current_employee_record_id() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER')));
create policy "hr manages assets" on public.assets for all to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER')) with check(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "visible custody history" on public.asset_custody_history for select to authenticated using(employee_id=public.current_employee_record_id() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "hr views maintenance" on public.asset_maintenance for select to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "hr manages maintenance" on public.asset_maintenance for all to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER')) with check(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create or replace function public.transfer_asset_custody(p_asset_id uuid,p_employee_id uuid,p_condition text,p_note text default null) returns text language plpgsql security definer set search_path=public as $$ declare old_employee uuid;action_name text;begin if public.current_role() not in ('SUPER_ADMIN','HR_MANAGER') then raise exception 'Not authorized';end if;select assigned_employee_id into old_employee from assets where id=p_asset_id and deleted_at is null for update;if not found then raise exception 'Asset not found';end if;action_name:=case when p_employee_id is null then 'RETURNED' when old_employee is null then 'ASSIGNED' else 'TRANSFERRED' end;update assets set assigned_employee_id=p_employee_id,status=case when p_employee_id is null then 'AVAILABLE' else 'ASSIGNED' end,condition=p_condition,updated_at=now() where id=p_asset_id;insert into asset_custody_history(asset_id,employee_id,action,condition,note,recorded_by) values(p_asset_id,p_employee_id,action_name,p_condition,p_note,auth.uid());insert into audit_logs(user_id,action,entity_type,entity_id,old_data,new_data) values(auth.uid(),'ASSET_'||action_name,'asset',p_asset_id::text,jsonb_build_object('employee_id',old_employee),jsonb_build_object('employee_id',p_employee_id,'condition',p_condition));return action_name;end $$;
revoke all on function public.transfer_asset_custody(uuid,uuid,text,text) from public,anon;grant execute on function public.transfer_asset_custody(uuid,uuid,text,text) to authenticated;

alter table public.announcements add column if not exists audience text not null default 'ALL' check(audience in ('ALL','MANAGERS','EMPLOYEES'));
alter table public.announcements add column if not exists publish_at timestamptz;
alter table public.announcements add column if not exists expires_at timestamptz;
alter table public.announcements add column if not exists requires_acknowledgement boolean not null default false;
create table public.announcement_acknowledgements(announcement_id uuid not null references public.announcements(id) on delete cascade,user_id uuid not null references public.users(id),acknowledged_at timestamptz not null default now(),primary key(announcement_id,user_id));
alter table public.announcement_acknowledgements enable row level security;
drop policy if exists "published announcements" on public.announcements;
create policy "targeted published announcements" on public.announcements for select to authenticated using(deleted_at is null and coalesce(published_at,publish_at)<=now() and (expires_at is null or expires_at>now()) and (audience='ALL' or (audience='MANAGERS' and public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER')) or (audience='EMPLOYEES' and public.current_role()='EMPLOYEE')));
create policy "hr manages announcements" on public.announcements for all to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER')) with check(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "own announcement acknowledgements" on public.announcement_acknowledgements for select to authenticated using(user_id=auth.uid() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "acknowledge visible announcement" on public.announcement_acknowledgements for insert to authenticated with check(user_id=auth.uid());
create or replace function public.acknowledge_announcement(p_announcement_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin if not exists(select 1 from announcements where id=p_announcement_id and requires_acknowledgement=true and deleted_at is null and coalesce(published_at,publish_at)<=now()) then raise exception 'Announcement is not available for acknowledgement';end if;insert into announcement_acknowledgements(announcement_id,user_id) values(p_announcement_id,auth.uid()) on conflict do nothing;end $$;
revoke all on function public.acknowledge_announcement(uuid) from public,anon;grant execute on function public.acknowledge_announcement(uuid) to authenticated;
